<script lang="ts">
  import { page } from '$app/state'; import { onDestroy } from 'svelte'; import { getConnector, pipelineErrorMessage, type ConnectorDefinition, type NexetlError } from '$lib/api/pipelines'; import Alert from '$lib/components/ui/Alert.svelte'; import LoadingState from '$lib/components/ui/LoadingState.svelte'; import Icon from '$lib/components/ui/Icon.svelte'; import { routeEntity } from '$lib/route-context';
  let connector = $state<ConnectorDefinition | null>(null), error = $state(''), loading = $state(true);
  $effect(() => { const key = page.params.connectorKey; if (key) void load(key); }); onDestroy(()=>routeEntity.set(null)); async function load(key: string) { loading = true; try { connector = await getConnector(key); routeEntity.set(connector.displayName); } catch (failure) { error = pipelineErrorMessage(failure as NexetlError); } finally { loading = false; } }
</script>
<svelte:head><title>{connector?.displayName ?? 'Connector'} | NEXETL</title></svelte:head>
{#if loading}<LoadingState />{:else if error}<Alert variant="error">{error}</Alert>{:else if connector}<a class="back" href="/connectors">← Connectors</a><header><span class="connector-icon"><Icon name="database" size={24}/></span><div><div class="title"><h1>{connector.displayName}</h1><span>{connector.availability === 'AVAILABLE' ? 'Available' : 'Coming later'}</span></div><p>{connector.vendor}</p></div></header><section><p class="eyebrow">Connector details</p><dl><div><dt>Category</dt><dd>{connector.category==='BOTH'?'Source + Target':connector.category}</dd></div><div><dt>Version</dt><dd>{connector.version}</dd></div><div><dt>Capabilities</dt><dd>{#each connector.capabilities as capability}<span class="tag">{capability}</span>{/each}</dd></div><div class="wide"><dt>Description</dt><dd>{connector.description}</dd></div></dl></section><Alert variant="info">Connection configuration is not part of the current authoring increment.</Alert>{/if}
